/* v231: Wer Wechselgeld schon nutzt, behält es sichtbar */if(S.ru&&S.ru.on&&!(S.featO&&'ru' in S.featO)){S.featO=S.featO||{};S.featO.ru=true}
const FEATP=['Einfach','Standard','Alles'];
const FEATK=Object.fromEntries(FEATS.flatMap(([,l])=>l.map(([k,n,p])=>[k,{n,p}])));
function featOn(k){const o=S.featO||{};if(k in o)return !!o[k];const d=FEATK[k];return d?!!d.p[S.featP==null?1:S.featP]:true}
function viewCfg(){const P=S.featP==null?1:S.featP,hasO=Object.keys(S.featO||{}).length;
 return appbar({title:'Funktionen',back:'setBack',noGear:true,sub:'Was in der App sichtbar ist'})+
 `<div class="sec"><div class="sh">Profil</div><div class="seg" id="fProf">${FEATP.map((n,i)=>`<button class="${P==i&&!hasO?'on':''}" data-fp="${i}">${n}</button>`).join('')}</div><div class="note">Ein Profil setzt alles auf einen Stand. Die Schalter darunter ändern das danach.</div></div>`+
 FEATS.map(([g,items])=>`<div class="sec"><div class="sh">${g}</div><div class="group">${items.map(([k,n,p])=>`<div class="cell plain"><div class="t"><div>${esc(n)}</div><div class="s">${FEATP.filter((x,i)=>p[i]).join(' · ')}</div></div><input type="checkbox" class="switch" data-fk="${k}" ${featOn(k)?'checked':''}></div>`).join('')}</div></div>`).join('')+
 `<div class="sec"><div class="group"><button class="cell" id="fReset"><div class="t"><div style="color:var(--blue)">Auf Profil zurücksetzen</div></div></button></div><div class="note">Ausgeblendet heißt nur nicht sichtbar. Deine Daten bleiben erhalten, und jede Funktion lässt sich jederzeit wieder einschalten.</div></div>`}
function bindCfg(){document.querySelectorAll('[data-fp]').forEach(b=>b.onclick=()=>{S.featP=+b.dataset.fp;S.featO={};save();render()});
 document.querySelectorAll('[data-fk]').forEach(i=>i.onchange=()=>{S.featO=S.featO||{};S.featO[i.dataset.fk]=i.checked;save();render()});
 if($('fReset'))$('fReset').onclick=()=>{S.featO={};save();render()}}


